<?php
// Manual exchange bridge. Legacy official forms and existing records are retained.
function sx_profile($p,$pid){$s=$p->prepare('SELECT full_name,position_name,position_level,employment_type FROM compensation_personnel WHERE id=?');$s->execute([$pid]);$r=$s->fetch(PDO::FETCH_ASSOC);foreach($r as &$v)$v=(string)$v;return $r;}
function sx_documents($p,$pid,$fy){
 $person=lt_person($p,$pid);$s=$p->prepare('SELECT body_json,revision FROM compensation_staff_exchange WHERE personnel_id=? AND fiscal_year=? AND kind=\'document\' ORDER BY item_key');$s->execute([$pid,$fy]);$docs=[];$seen=[];
 foreach($s->fetchAll(PDO::FETCH_ASSOC) as $r){$d=json_decode($r['body_json'],true);$d['revision']=(int)$r['revision'];$docs[]=$d;$seen[$d['form_code'].':'.($d['period_month']??'')]=true;}
 // Match by the personnel's explicit employee code, or exact unique full name. Never fuzzy-match.
 $s=$p->prepare('SELECT employee_code,full_name FROM compensation_personnel WHERE id=?');$s->execute([$pid]);$identity=$s->fetch();
 if($identity['employee_code']){$where='employee_code=?';$match=$identity['employee_code'];}
 else{$s=$p->prepare('SELECT COUNT(*) FROM compensation_personnel WHERE full_name=?');$s->execute([$identity['full_name']]);if((int)$s->fetchColumn()!==1)throw new RuntimeException('ชื่อซ้ำ ต้องกำหนดรหัสบุคลากรก่อนส่งออก ฉ.11');$where='full_name=?';$match=$identity['full_name'];}
 $s=$p->prepare('SELECT * FROM compensation_records WHERE fiscal_year=? AND '.$where.' ORDER BY id DESC LIMIT 200');$s->execute([$fy,$match]);$records=$s->fetchAll(PDO::FETCH_ASSOC);if(count($records)>=200)throw new RuntimeException('เอกสารเดิมมากเกิน ต้องแบ่งตรวจข้อมูลก่อน');
 foreach($records as $r){$code=$r['form_type']==='annual'?'chor11_annual':'chor11_monthly';$m=(int)$r['payment_month'];$period=$code==='chor11_annual'?null:sprintf('%04d-%02d-01',$fy-543-($m>=10?1:0),$m);$key=$code.':'.($period??'');if(isset($seen[$key]))continue;
  $a=$p->prepare('SELECT * FROM compensation_application_details WHERE record_id=?');$a->execute([$r['id']]);$f=$a->fetch(PDO::FETCH_ASSOC)?:[];unset($f['record_id']);
  foreach(['full_name','position_name','work_date_from','work_date_to','total_amount','note'] as $field)if($r[$field]!==null)$f[$field]=$r[$field];
  $f['facility_name']=$r['department']??'';$f['compensation_category']='LUMP_SUM_ALLOWANCE';$f['certificate_verified']=0;
  $h=$p->prepare('SELECT facility_name,province,level_name,start_date,end_date,duration_years,duration_months,duration_days FROM compensation_service_history WHERE record_id=? ORDER BY sequence_no,id');$h->execute([$r['id']]);$histories=$h->fetchAll(PDO::FETCH_ASSOC);foreach($histories as &$history){foreach($history as $k=>&$v){if(strpos($k,'duration_')===0)$v=(int)$v;elseif($v===null)$v='';}unset($v);}unset($history);$f['service_history']=lt_json($histories);
  $i=$p->prepare('SELECT rate FROM compensation_items WHERE record_id=? ORDER BY sort_order,id');$i->execute([$r['id']]);$rates=$i->fetchAll(PDO::FETCH_COLUMN);if(count($rates)===1)$f['monthly_rate']=(float)$rates[0];
  $common=['applicant_first_name','applicant_last_name','service_as_of','full_name','position_name','position_level','employment_type','facility_name','request_date','monthly_rate','note','compensation_category','work_date_from','work_date_to','bureau','unit_moo','unit_subdistrict','unit_district','unit_province','level_name','service_years','service_months','service_days'];
  $extra=$code==='chor11_annual'?['written_at','license_type','license_number','contact_address','address_no','road','address_subdistrict','address_district','address_province','postcode','license_other','license_issue_date','no_professional_license','duration_years','duration_months','duration_hours','total_amount','amount_in_words']:['training_status','training_years','training_months','training_regional_selected','training_district_selected','training_regional_facility','training_regional_province','training_regional_from_date','training_regional_to_date','training_district_facility','training_district_province','training_district_from_date','training_district_to_date','period_month','work_days','leave_days','total_amount','service_history','history_print_names','calendar_work_days','certificate_verified','head_name','head_position','director_name','director_position'];
  $f=array_intersect_key($f,array_flip(array_merge($common,$extra)));$numbers=['monthly_rate','total_amount','service_years','service_months','service_days','no_professional_license','duration_years','duration_months','duration_hours','certificate_verified','work_days','leave_days','calendar_work_days'];foreach($f as $k=>&$v){if($v===null){unset($f[$k]);continue;}if(in_array($k,$numbers,true))$v=(float)$v;}unset($v);
  $docs[]=['id'=>lt_map($p,'document',$r['id']),'form_code'=>$code,'template_version'=>'2569.1','fiscal_year'=>$fy,'period_month'=>$period,'status'=>'draft','form_data'=>(object)$f,'revision'=>1,'legacy_record_id'=>$r['id']];$seen[$key]=true;
 }
 if(count($docs)>13)throw new RuntimeException('เอกสารต่อคนต่อปีเกิน 13 ใบ');return $docs;
}
function sx_snapshot($p,$pid,$fy){$leave=lt_snapshot($p,$pid,$fy);$s=$p->prepare('SELECT body_json FROM compensation_staff_exchange WHERE personnel_id=? AND fiscal_year=0 AND kind=\'photo\'');$s->execute([$pid]);$photo=$s->fetchColumn();$profile=sx_profile($p,$pid);return ['leave'=>$leave,'staff'=>['profile'=>$profile,'documents'=>sx_documents($p,$pid,$fy),'photo'=>$photo?json_decode($photo):null],'revision'=>hash('sha256',lt_json($profile))];}
function sx_validate_document($d,$fy){if(!lt_uuid($d['id']??null)||!in_array($d['form_code']??'', ['chor11_annual','chor11_monthly'],true)||($d['template_version']??'')!=='2569.1'||(int)($d['fiscal_year']??0)!==$fy||!isset($d['form_data'])||!is_array($d['form_data'])||strlen(lt_json($d['form_data']))>20000)throw new RuntimeException('รูปแบบเอกสาร/รุ่น/ขนาดไม่ถูกต้อง');$period=$d['period_month']??null;if($d['form_code']==='chor11_annual'){if($period!==null)throw new RuntimeException('คำขอประจำปีต้องไม่มีเดือน');}elseif(!in_array($period,wd_months($fy),true))throw new RuntimeException('เดือนเอกสารผิดปี');return $d['form_code'].':'.($period??'');}
function sx_save($p,$pid,$fy,$d,$expected){$person=lt_person($p,$pid);lt_map($p,'person',$pid);$key=sx_validate_document($d,$fy);$s=$p->prepare('SELECT revision FROM compensation_staff_exchange WHERE personnel_id=? AND fiscal_year=? AND kind=\'document\' AND item_key=? FOR UPDATE');$s->execute([$pid,$fy,$key]);$old=$s->fetchColumn();if($old!==false&&(int)$old!==$expected)throw new RuntimeException('เอกสารมีผู้แก้ก่อนแล้ว');if($old===false&&$expected!==0)throw new RuntimeException('เอกสารเปลี่ยน กรุณาเปิดใหม่');$d['status']='draft';unset($d['legacy_record_id'],$d['issue_history'],$d['confirmed_by'],$d['confirmed_at'],$d['issue_count']);$d['revision']=$old===false?1:(int)$old+1;$d['form_data']=array_merge($d['form_data'],sx_profile($p,$pid));$d['recorded_at']=date('c');$d['recorded_by']=function_exists('currentUser')?(int)currentUser()['id']:0;
 $s=$p->prepare('INSERT INTO compensation_staff_exchange(personnel_id,fiscal_year,kind,item_key,body_json,revision) VALUES(?,?,\'document\',?,?,?) ON DUPLICATE KEY UPDATE body_json=VALUES(body_json),revision=VALUES(revision)');$s->execute([$pid,$fy,$key,lt_json($d),$d['revision']]);return $d;
}
function sx_apply($p,$pid,$fy,$part,$packet,$before){$validation=$packet;if(($packet['source_instance']??'')===lt_config()['instance'])$validation['source_instance']=lt_config()['trusted_source'];$identity=lt_person($p,$pid);$identity['id']=lt_map($p,'person',$pid);lt_validate($validation,['person'=>$identity,'year'=>$fy]);$staff=$packet['staff_data']??[];if(($staff['version']??null)!==1)throw new RuntimeException('ไม่รองรับชุดข้อมูล');
 $p->beginTransaction();try{$lock=$p->prepare('SELECT id FROM compensation_personnel WHERE id=? FOR UPDATE');$lock->execute([$pid]);$fresh=sx_snapshot($p,$pid,$fy);if(!in_array($part,['profile','documents','photo'],true)||!lt_equal(lt_array($fresh['staff'][$part]??null),lt_array($before['staff'][$part]??null)))throw new RuntimeException('ข้อมูลเปลี่ยน กรุณาตรวจแฟ้มใหม่');
  if($part==='profile'){$limits=['full_name'=>150,'position_name'=>150,'position_level'=>100,'employment_type'=>80];foreach($limits as $k=>$n)if(!is_string($staff['profile'][$k]??null)||mb_strlen($staff['profile'][$k])>$n||($k==='full_name'&&trim($staff['profile'][$k])===''))throw new RuntimeException('ชื่อ/ตำแหน่งเกินขนาดที่ local รองรับ จึงไม่ตัดข้อความ');$x=$staff['profile'];if($x['full_name']!==$fresh['staff']['profile']['full_name'])throw new RuntimeException('ชื่อเต็มต่างจากทะเบียน local ให้ตรวจแก้คำนำหน้า/ชื่อ/นามสกุลในทะเบียนบุคลากรก่อน ไม่แยกชื่ออัตโนมัติ');$p->prepare('UPDATE compensation_personnel SET position_name=?,position_level=?,employment_type=? WHERE id=?')->execute([$x['position_name'],$x['position_level'],$x['employment_type'],$pid]);$message='ตำแหน่ง/ระดับ: บันทึกในทะเบียน local แล้ว';}
  elseif($part==='photo'){if(empty($staff['photo'])){$message='รูป: ต้นทางไม่มีรูป คงรูปเดิม';}else{$photo=$staff['photo'];$bytes=base64_decode($photo['data']??'',true);$image=$bytes===false?false:@getimagesizefromstring($bytes);if(($photo['type']??'')!=='image/webp'||!$image||$image['mime']!=='image/webp'||strlen($bytes)>102400||$image[0]>400||$image[1]>500)throw new RuntimeException('รูปต้องเป็น WebP ไม่เกิน 100 KB และ 400×500 พิกเซล');$p->prepare('INSERT INTO compensation_staff_exchange(personnel_id,fiscal_year,kind,item_key,body_json,revision) VALUES(?,0,\'photo\',\'portrait\',?,1) ON DUPLICATE KEY UPDATE body_json=VALUES(body_json),revision=revision+1')->execute([$pid,lt_json($photo)]);$message='รูป: บันทึกและเปิดดูใน local ได้แล้ว';}}
  elseif($part==='documents'){if(!is_array($staff['documents']??null)||count($staff['documents'])>13)throw new RuntimeException('จำนวนเอกสารเกินกำหนด');$keys=[];foreach($staff['documents'] as $d){$key=sx_validate_document($d,$fy);if(isset($keys[$key]))throw new RuntimeException('เอกสารซ้ำ');$keys[$key]=true;$s=$p->prepare('SELECT revision FROM compensation_staff_exchange WHERE personnel_id=? AND fiscal_year=? AND kind=\'document\' AND item_key=?');$s->execute([$pid,$fy,$key]);$revision=$s->fetchColumn();if($d['form_code']==='chor11_monthly')$d['form_data']['certificate_verified']=0;sx_save($p,$pid,$fy,$d,$revision===false?0:(int)$revision);}$message='ฉ.11: รับเป็นร่าง '.count($keys).' ใบ เปิดแก้และพิมพ์ในเมนู ฉ.11 รับส่งได้';}
  else throw new RuntimeException('ไม่รองรับส่วนข้อมูล');$s=$p->query('SELECT COALESCE(SUM(OCTET_LENGTH(body_json)),0) FROM compensation_staff_exchange');if((int)$s->fetchColumn()>25*1024*1024)throw new RuntimeException('พื้นที่รับส่ง local เกิน 25 MB ให้ผู้เขียนจัดเก็บย้อนหลัง');$p->commit();return ['message'=>$message];
 }catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;}}
